package com.galesong.runecards;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

@Singleton
public class PackEarnedOverlay extends Overlay
{
	private static final long DISPLAY_MS = 4_500L;
	private static final long FADE_MS = 500L;
	private static final int WIDTH = 280;
	private static final int HEIGHT = 64;
	private static final BufferedImage ICON = ImageUtil.loadImageResource(PackEarnedOverlay.class, "/runecards/icon.png");

	private final Client client;
	private volatile long shownAt;
	private volatile long visibleUntil;

	@Inject
	public PackEarnedOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_MED);
	}

	void showPackEarned()
	{
		long now = System.currentTimeMillis();
		shownAt = now;
		visibleUntil = now + DISPLAY_MS;
	}

	void hide()
	{
		shownAt = 0L;
		visibleUntil = 0L;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.currentTimeMillis();
		long until = visibleUntil;
		if (until == 0L || now >= until)
		{
			return null;
		}

		float appear = Math.min(1f, Math.max(0f, (now - shownAt) / 220f));
		float disappear = Math.min(1f, Math.max(0f, (until - now) / (float) FADE_MS));
		float alpha = Math.min(appear, disappear);
		int x = Math.max(8, (client.getCanvasWidth() - WIDTH) / 2);
		int y = 42 - Math.round((1f - appear) * 12f);

		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setComposite(AlphaComposite.SrcOver.derive(alpha));
			g.setColor(new Color(0x17130F));
			g.fillRoundRect(x, y, WIDTH, HEIGHT, 12, 12);
			g.setStroke(new BasicStroke(2f));
			g.setColor(new Color(0xD5A33B));
			g.drawRoundRect(x + 1, y + 1, WIDTH - 3, HEIGHT - 3, 12, 12);

			if (ICON != null)
			{
				g.drawImage(ICON.getScaledInstance(38, 38, Image.SCALE_SMOOTH), x + 13, y + 13, null);
			}
			Font title = FontManager.getRunescapeBoldFont().deriveFont(16f);
			Font body = FontManager.getRunescapeSmallFont().deriveFont(12f);
			g.setFont(title);
			g.setColor(new Color(0xF2D79A));
			g.drawString("RuneCards pack earned!", x + 61, y + 27);
			g.setFont(body);
			g.setColor(Color.LIGHT_GRAY);
			g.drawString("Open it from the RuneCards sidebar.", x + 61, y + 47);
		}
		finally
		{
			g.dispose();
		}
		return null;
	}
}

package com.galesong.runecards;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RuneCardsConfig.GROUP)
public interface RuneCardsConfig extends Config
{
	String GROUP = "runecards";

	@ConfigItem(
		keyName = "automaticSlayerTasks",
		name = "Detect completed tasks",
		description = "Automatically records genuine Slayer task counter increases",
		position = 0
	)
	default boolean automaticSlayerTasks()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyPackFound",
		name = "Pack notifications",
		description = "Sends a RuneLite notification when a Slayer task awards a pack",
		position = 1
	)
	default boolean notifyPackFound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "packEarnedPopup",
		name = "In-game pack popup",
		description = "Shows a small non-blocking popup when a Slayer task awards a pack",
		position = 2
	)
	default boolean packEarnedPopup()
	{
		return true;
	}
}

package com.galesong.runecards;

import com.galesong.runecards.model.CardDefinition;
import com.galesong.runecards.model.RuneCardsData;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class RuneCardsDataService
{
	private final Gson gson;
	private RuneCardsData config;
	private List<CardDefinition> cards;

	@Inject
	public RuneCardsDataService(Gson gson)
	{
		this.gson = gson;
	}

	public void load() throws IOException
	{
		config = readResource("/runecards/config.json", RuneCardsData.class);
		CardDefinition[] loadedCards = readResource("/runecards/cards.json", CardDefinition[].class);
		CardDefinition[] loadedQuests = readResource("/runecards/quests.json", CardDefinition[].class);
		cards = new ArrayList<>(loadedCards.length + loadedQuests.length);
		cards.addAll(Arrays.asList(loadedCards));
		cards.addAll(Arrays.asList(loadedQuests));
		cards = Collections.unmodifiableList(cards);
	}

	public RuneCardsData getConfig()
	{
		ensureLoaded();
		return config;
	}

	public List<CardDefinition> getCards()
	{
		ensureLoaded();
		return cards;
	}

	private <T> T readResource(String path, Class<T> type) throws IOException
	{
		try (InputStream stream = RuneCardsDataService.class.getResourceAsStream(path))
		{
			if (stream == null)
			{
				throw new IOException("Missing bundled resource: " + path);
			}
			try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
			{
				T value = gson.fromJson(reader, type);
				if (value == null)
				{
					throw new IOException("Invalid bundled resource: " + path);
				}
				return value;
			}
		}
	}

	private void ensureLoaded()
	{
		if (config == null || cards == null)
		{
			throw new IllegalStateException("RuneCards data has not been loaded");
		}
	}
}

package com.galesong.runecards;

import com.galesong.runecards.model.CardDefinition;
import com.galesong.runecards.model.Effect;
import com.galesong.runecards.model.Gate;
import com.galesong.runecards.model.HistoryEntry;
import com.galesong.runecards.model.MasterProgress;
import com.galesong.runecards.model.Requirement;
import com.galesong.runecards.model.RuneCardsData;
import com.galesong.runecards.model.RuneCardsState;
import com.galesong.runecards.model.SlayerMasterDefinition;
import com.galesong.runecards.model.TaskLogEntry;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;

public class RuneCardsEngine
{
	// Swing actions and client-thread Slayer events share this monitor.
	// Callers traversing the mutable state must also hold it.
	private final RuneCardsData config;
	private final List<CardDefinition> cards;
	private final Map<String, CardDefinition> cardsById;
	private final Random random;
	private RuneCardsState state;

	public RuneCardsEngine(RuneCardsData config, List<CardDefinition> cards, Random random)
	{
		this.config = config;
		this.cards = Collections.unmodifiableList(new ArrayList<>(cards));
		this.cardsById = cards.stream().collect(Collectors.toMap(
			CardDefinition::getId,
			card -> card,
			(first, second) ->
			{
				throw new IllegalArgumentException("Duplicate card id: " + first.getId());
			},
			LinkedHashMap::new));
		this.random = random;
		this.state = createDefaultState();
	}

	private RuneCardsState createDefaultState()
	{
		RuneCardsState fresh = new RuneCardsState();
		fresh.setUnlockHistory(new ArrayList<>());
		fresh.setSkillCaps(new LinkedHashMap<>(config.getInitialCaps()));
		for (SlayerMasterDefinition master : config.getMasters())
		{
			fresh.getSlayerMasters().put(master.getId(), new MasterProgress(0, 0, master.getMaxPacks(), 0));
		}
		if (!config.getMasters().isEmpty())
		{
			fresh.setSelectedMasterId(config.getMasters().get(0).getId());
		}
		return fresh;
	}

	public synchronized void loadState(RuneCardsState loaded)
	{
		state = migrate(loaded == null ? createDefaultState() : loaded);
	}

	public synchronized RuneCardsState getState()
	{
		return state;
	}

	public List<CardDefinition> getCards()
	{
		return cards;
	}

	public RuneCardsData getConfig()
	{
		return config;
	}

	public CardDefinition getCard(String id)
	{
		return id == null ? null : cardsById.get(id);
	}

	public synchronized List<CardDefinition> openPack()
	{
		if (state.getActiveCardId() != null)
		{
			throw new IllegalStateException("Complete the active card first.");
		}
		if (!state.getPendingPackOptionIds().isEmpty())
		{
			throw new IllegalStateException("Choose a card from the current pack first.");
		}
		if (state.getUnopenedPacks() <= 0)
		{
			throw new IllegalStateException("No unopened packs.");
		}

		Set<String> completed = new HashSet<>(state.getCompletedCardIds());
		List<CardDefinition> eligible = cards.stream()
			.filter(card -> requirementsMet(card, completed))
			.filter(card -> card.isRepeatable() || !completed.contains(card.getId()))
			.collect(Collectors.toList());
		if (eligible.isEmpty())
		{
			throw new IllegalStateException("No eligible cards right now.");
		}

		List<CardDefinition> options = drawPackOptions(eligible, config.getCardsPerPack());
		state.setUnopenedPacks(state.getUnopenedPacks() - 1);
		state.setPacksOpened(state.getPacksOpened() + 1);
		List<String> ids = options.stream().map(CardDefinition::getId).collect(Collectors.toList());
		state.setPendingPackOptionIds(new ArrayList<>(ids));
		state.setLastPackOptionIds(new ArrayList<>(ids));
		touch();
		return options;
	}

	public synchronized void chooseCard(String id)
	{
		CardDefinition card = cardsById.get(id);
		if (card == null || !state.getPendingPackOptionIds().contains(id))
		{
			throw new IllegalArgumentException("That card is not in the current pack.");
		}
		state.setActiveCardId(id);
		state.setActiveGate(card.getGate());
		state.setPendingPackOptionIds(new ArrayList<>());
		state.setLastPackPickedId(id);
		if (!state.getObtainedCardIds().contains(id))
		{
			state.getObtainedCardIds().add(id);
		}
		state.getUnlockHistory().add(0, new HistoryEntry(id, card.getTitle(), Instant.now().toString()));
		applyUnlockEffects(card);
		touch();
	}

	public synchronized void completeActiveCard(Map<String, Integer> actualLevels)
	{
		CardDefinition card = cardsById.get(state.getActiveCardId());
		if (card == null)
		{
			throw new IllegalStateException("No active card.");
		}
		Gate gate = state.getActiveGate();
		if (gate != null && Gate.REACH_LEVEL.equals(gate.getKind()))
		{
			int actualLevel = actualLevels.getOrDefault(gate.getSkill(), 1);
			if (actualLevel < gate.getLevel())
			{
				throw new IllegalStateException(gate.getSkill() + " level " + gate.getLevel() + " has not been reached.");
			}
		}
		if (!card.isRepeatable() && !state.getCompletedCardIds().contains(card.getId()))
		{
			state.getCompletedCardIds().add(card.getId());
		}
		state.getTaskLog().add(0, new TaskLogEntry(card.getId(), card.getTitle(), Instant.now().toString()));
		state.setActiveCardId(null);
		state.setActiveGate(null);
		touch();
	}

	public synchronized TaskResult completeSlayerTask(String masterId)
	{
		MasterProgress progress = state.getSlayerMasters().get(masterId);
		if (progress == null)
		{
			throw new IllegalArgumentException("Unknown Slayer Master: " + masterId);
		}
		progress.setTasks(progress.getTasks() + 1);
		if (progress.getPacksFound() >= progress.getMaxPacks())
		{
			touch();
			return new TaskResult(false, true);
		}

		double chance = slayerChance(progress);
		boolean found = random.nextDouble() < chance;
		if (found)
		{
			progress.setPacksFound(progress.getPacksFound() + 1);
			progress.setSinceLastPack(0);
			state.setUnopenedPacks(state.getUnopenedPacks() + 1);
		}
		else
		{
			progress.setSinceLastPack(progress.getSinceLastPack() + 1);
		}
		touch();
		return new TaskResult(found, false);
	}

	public synchronized void setSelectedMaster(String masterId)
	{
		if (!state.getSlayerMasters().containsKey(masterId))
		{
			throw new IllegalArgumentException("Unknown Slayer Master: " + masterId);
		}
		state.setSelectedMasterId(masterId);
		touch();
	}

	public synchronized String getSelectedMasterId()
	{
		return state.getSelectedMasterId();
	}

	public synchronized int getTotalSlayerTasks()
	{
		return state.getSlayerMasters().values().stream().mapToInt(MasterProgress::getTasks).sum();
	}

	public synchronized double slayerChance(MasterProgress progress)
	{
		int maxPacks = progress.getMaxPacks();
		int remaining = Math.max(0, maxPacks - progress.getPacksFound());
		if (maxPacks <= 0 || remaining <= 0)
		{
			return 0;
		}
		double base = config.getPackChancePerSlayerTask();
		double start = Math.min(config.getSlayerChanceCap(), base * config.getSlayerStartMultiplier());
		double end = Math.min(config.getSlayerChanceCap(), base * config.getSlayerEndMultiplier());
		double ratio = (double) remaining / maxPacks;
		double pity = Math.min(config.getSlayerPityCap(), progress.getSinceLastPack() * config.getSlayerPityPerTask());
		return Math.min(config.getSlayerChanceCap(), end + (start - end) * Math.pow(ratio, config.getSlayerChanceCurve()) + pity);
	}

	private boolean requirementsMet(CardDefinition card, Set<String> completed)
	{
		for (Requirement requirement : card.getRequirements())
		{
			if (Requirement.SKILL_CAP_AT_LEAST.equals(requirement.getKind()))
			{
				if (state.getSkillCaps().getOrDefault(requirement.getSkill(), 1) < requirement.getCap())
				{
					return false;
				}
			}
			else if (Requirement.CARD_COMPLETED.equals(requirement.getKind()))
			{
				if (!completed.contains(requirement.getCardId()))
				{
					return false;
				}
			}
			else
			{
				return false;
			}
		}
		return true;
	}

	private RuneCardsState migrate(RuneCardsState loaded)
	{
		loaded.setVersion(5);
		loaded.setPlatform("runelite");
		if (loaded.getTaskLog() == null) loaded.setTaskLog(new ArrayList<>());
		if (loaded.getPendingPackOptionIds() == null) loaded.setPendingPackOptionIds(new ArrayList<>());
		if (loaded.getLastPackOptionIds() == null) loaded.setLastPackOptionIds(new ArrayList<>());
		if (loaded.getObtainedCardIds() == null) loaded.setObtainedCardIds(new ArrayList<>());
		if (loaded.getCompletedCardIds() == null) loaded.setCompletedCardIds(new ArrayList<>());
		if (loaded.getReachedLevels() == null) loaded.setReachedLevels(new HashMap<>());
		if (loaded.getUnlockHistory() == null)
		{
			// Older RuneCards saves recorded obtained IDs before unlock history existed.
			List<HistoryEntry> history = new ArrayList<>();
			for (String id : loaded.getObtainedCardIds())
			{
				CardDefinition card = getCard(id);
				history.add(new HistoryEntry(id, card == null ? id : card.getTitle(), null));
			}
			Collections.reverse(history);
			loaded.setUnlockHistory(history);
		}

		Map<String, Integer> caps = new LinkedHashMap<>(config.getInitialCaps());
		if (loaded.getSkillCaps() != null) caps.putAll(loaded.getSkillCaps());
		loaded.setSkillCaps(caps);

		Map<String, MasterProgress> existing = loaded.getSlayerMasters() == null
			? Collections.emptyMap() : loaded.getSlayerMasters();
		Map<String, MasterProgress> masters = new LinkedHashMap<>();
		for (SlayerMasterDefinition definition : config.getMasters())
		{
			MasterProgress progress = existing.get(definition.getId());
			if (progress == null)
			{
				progress = new MasterProgress();
			}
			progress.setMaxPacks(definition.getMaxPacks());
			masters.put(definition.getId(), progress);
		}
		loaded.setSlayerMasters(masters);

		if (!masters.containsKey(loaded.getSelectedMasterId()))
		{
			loaded.setSelectedMasterId(config.getMasters().isEmpty() ? null : config.getMasters().get(0).getId());
		}
		return loaded;
	}

	private List<CardDefinition> drawPackOptions(List<CardDefinition> eligible, int count)
	{
		List<CardDefinition> pool = new ArrayList<>(eligible);
		List<CardDefinition> options = new ArrayList<>();
		if (count >= 3)
		{
			List<CardDefinition> nonQuests = pool.stream()
				.filter(card -> !CardDefinition.QUEST.equals(card.getType()))
				.collect(Collectors.toList());
			if (!nonQuests.isEmpty())
			{
				CardDefinition first = weightedPick(nonQuests);
				options.add(first);
				pool.removeIf(card -> card.getId().equals(first.getId()));
			}
		}
		while (!pool.isEmpty() && options.size() < count)
		{
			CardDefinition picked = weightedPick(pool);
			options.add(picked);
			pool.removeIf(card -> card.getId().equals(picked.getId()));
		}
		return options;
	}

	private CardDefinition weightedPick(List<CardDefinition> pool)
	{
		double total = pool.stream().mapToDouble(card -> Math.max(0, card.getWeight())).sum();
		if (total <= 0)
		{
			return pool.get(random.nextInt(pool.size()));
		}
		double roll = random.nextDouble() * total;
		for (CardDefinition card : pool)
		{
			roll -= Math.max(0, card.getWeight());
			if (roll < 0)
			{
				return card;
			}
		}
		return pool.get(pool.size() - 1);
	}

	private void applyUnlockEffects(CardDefinition card)
	{
		for (Effect effect : card.getUnlockEffects())
		{
			if (Effect.SET_SKILL_CAP.equals(effect.getKind()))
			{
				int current = state.getSkillCaps().getOrDefault(effect.getSkill(), 1);
				state.getSkillCaps().put(effect.getSkill(), Math.max(current, effect.getCap()));
			}
		}
	}

	private void touch()
	{
		state.setSavedAt(Instant.now().toString());
	}

	public static final class TaskResult
	{
		private final boolean packFound;
		private final boolean masterComplete;

		TaskResult(boolean packFound, boolean masterComplete)
		{
			this.packFound = packFound;
			this.masterComplete = masterComplete;
		}

		public boolean isPackFound()
		{
			return packFound;
		}

		public boolean isMasterComplete()
		{
			return masterComplete;
		}
	}
}

package com.galesong.runecards;

import com.galesong.runecards.model.CardDefinition;
import com.galesong.runecards.model.HistoryEntry;
import com.galesong.runecards.model.MasterProgress;
import com.galesong.runecards.model.RuneCardsState;
import com.galesong.runecards.model.SlayerMasterDefinition;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class RuneCardsPanel extends PluginPanel
{
	private final RuneCardsPlugin plugin;
	private final RuneCardsEngine engine;
	private final JLabel packsValue = valueLabel();
	private final JLabel completedValue = valueLabel();
	private final JLabel tasksValue = valueLabel();
	private final JLabel activeCard = new JLabel();
	private final JLabel masterProgress = new JLabel();
	private final JLabel status = new JLabel(" ");
	private final JButton openPackButton = new JButton("Open Pack");
	private final JPanel packOptions = verticalPanel();
	private final JPanel history = verticalPanel();
	private final JComboBox<SlayerMasterDefinition> masterSelector;
	private final List<String> displayedPackOptionIds = new ArrayList<>();
	private final Set<String> revealedPackOptionIds = new HashSet<>();
	private boolean refreshing;

	RuneCardsPanel(RuneCardsPlugin plugin, RuneCardsEngine engine)
	{
		super(false);
		this.plugin = plugin;
		this.engine = engine;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		masterSelector = new JComboBox<>(engine.getConfig().getMasters().toArray(new SlayerMasterDefinition[0]));
		masterSelector.addActionListener(event ->
		{
			if (!refreshing && masterSelector.getSelectedItem() != null)
			{
				plugin.selectMaster(((SlayerMasterDefinition) masterSelector.getSelectedItem()).getId());
			}
		});

		JPanel root = new ViewportWidthPanel();
		root.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		root.add(title("RuneCards"));
		root.add(Box.createRigidArea(new Dimension(0, 6)));
		root.add(buildStats());
		root.add(Box.createRigidArea(new Dimension(0, 6)));
		root.add(buildTabs());
		root.add(Box.createRigidArea(new Dimension(0, 6)));
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		root.add(buildFooter());

		JScrollPane scrollPane = new JScrollPane(
			root,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
			JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setBorder(null);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		add(scrollPane, BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		int unopenedPacks;
		int completedCards;
		int totalTasks;
		String activeId;
		String masterId;
		List<String> options;
		List<HistoryEntry> unlocks;
		MasterProgress progress;
		double chance;
		synchronized (engine)
		{
			RuneCardsState state = engine.getState();
			unopenedPacks = state.getUnopenedPacks();
			completedCards = state.getCompletedCardIds().size();
			totalTasks = engine.getTotalSlayerTasks();
			activeId = state.getActiveCardId();
			masterId = state.getSelectedMasterId();
			options = new ArrayList<>(state.getPendingPackOptionIds());
			List<HistoryEntry> historyEntries = state.getUnlockHistory();
			unlocks = new ArrayList<>(historyEntries.subList(0, Math.min(12, historyEntries.size())));
			MasterProgress current = state.getSlayerMasters().get(masterId);
			progress = current == null ? null : new MasterProgress(current.getTasks(),
				current.getPacksFound(), current.getMaxPacks(), current.getSinceLastPack());
			chance = current == null ? 0 : engine.slayerChance(current) * 100;
		}
		refreshing = true;
		try
		{
			packsValue.setText(String.valueOf(unopenedPacks));
			completedValue.setText(completedCards + "/" + engine.getCards().size());
			tasksValue.setText(String.valueOf(totalTasks));
			updatePackButton(!options.isEmpty(), activeId, unopenedPacks);
			updateActiveCard(activeId);
			updatePackOptions(options);
			updateSlayerProgress(masterId, progress, chance);
			updateHistory(unlocks);
		}
		finally
		{
			refreshing = false;
		}
		revalidate();
		repaint();
	}

	private void updatePackButton(boolean hasPendingPack, String activeId, int unopenedPacks)
	{
		openPackButton.setText(hasPendingPack ? "Choose Below" : "Open Pack");
		openPackButton.setEnabled(!hasPendingPack
			&& activeId == null && unopenedPacks > 0);
		openPackButton.setToolTipText(hasPendingPack
			? "Choose one of the four cards listed below"
			: "Open one earned card pack");
	}

	private void updateActiveCard(String activeId)
	{
		CardDefinition active = engine.getCard(activeId);
		activeCard.setText(active == null
			? htmlBlock("<b>No active card</b><br>Open a pack to draw four options.")
			: htmlBlock("<b>" + html(active.getTitle()) + "</b><br>" + html(active.getDescription())));
	}

	private void updatePackOptions(List<String> pendingPackOptionIds)
	{
		packOptions.removeAll();
		if (!displayedPackOptionIds.equals(pendingPackOptionIds))
		{
			displayedPackOptionIds.clear();
			displayedPackOptionIds.addAll(pendingPackOptionIds);
			revealedPackOptionIds.clear();
		}
		for (int index = 0; index < pendingPackOptionIds.size(); index++)
		{
			String id = pendingPackOptionIds.get(index);
			CardDefinition card = engine.getCard(id);
			if (card == null) continue;
			boolean revealed = revealedPackOptionIds.contains(id);
			JButton choose = compact(new JButton(revealed
				? "Pick: " + shorten(card.getTitle(), 24)
				: "Reveal card " + (index + 1)));
			choose.setToolTipText(revealed ? card.getDescription() : "Reveal this card");
			choose.addActionListener(event ->
			{
				if (revealedPackOptionIds.add(card.getId()))
				{
					refresh();
				}
				else
				{
					plugin.chooseCard(card.getId());
				}
			});
			packOptions.add(choose);
			packOptions.add(Box.createRigidArea(new Dimension(0, 4)));
		}
		if (pendingPackOptionIds.isEmpty())
		{
			packOptions.add(new JLabel("No pack is currently open."));
		}
	}

	private void updateSlayerProgress(String masterId, MasterProgress progress, double chance)
	{
		selectMaster(masterId);
		if (progress != null)
		{
			masterProgress.setText(String.format(
				htmlBlock("<b>%d/%d packs</b><br>%d tasks &middot; %.1f%% chance &middot; pity %d"),
				progress.getPacksFound(), progress.getMaxPacks(), progress.getTasks(), chance,
				progress.getSinceLastPack()));
		}
	}

	private void updateHistory(List<HistoryEntry> unlocks)
	{
		history.removeAll();
		for (int index = 0; index < Math.min(12, unlocks.size()); index++)
		{
			HistoryEntry entry = unlocks.get(index);
			history.add(compact(new JLabel(htmlBlock("&bull; " + html(entry.getTitle())))));
			history.add(Box.createRigidArea(new Dimension(0, 3)));
		}
		if (unlocks.isEmpty()) history.add(new JLabel("No cards unlocked yet."));
	}

	void showStatus(String message)
	{
		status.setText(htmlBlock(html(message)));
		compact(status);
	}

	private JPanel buildStats()
	{
		JPanel stats = new JPanel(new GridLayout(1, 3, 4, 0));
		stats.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		stats.add(stat("PACKS", packsValue));
		stats.add(stat("CARDS", completedValue));
		stats.add(stat("TASKS", tasksValue));
		return compact(stats);
	}

	private JTabbedPane buildTabs()
	{
		JTabbedPane tabs = new JTabbedPane();
		tabs.addTab("Cards", buildCardsTab());
		tabs.addTab("Slayer", buildSlayerTab());
		tabs.addTab("Log", history);
		tabs.setAlignmentX(LEFT_ALIGNMENT);
		return tabs;
	}

	private JPanel buildCardsTab()
	{
		JPanel cards = verticalPanel();
		cards.setBorder(BorderFactory.createEmptyBorder(8, 4, 8, 4));
		cards.add(activeCard);
		cards.add(Box.createRigidArea(new Dimension(0, 8)));

		JPanel actions = new JPanel(new GridLayout(1, 2, 4, 0));
		openPackButton.addActionListener(event -> plugin.openPack());
		JButton complete = new JButton("Complete");
		complete.addActionListener(event -> plugin.completeActiveCard());
		actions.add(openPackButton);
		actions.add(complete);
		cards.add(compact(actions));
		cards.add(Box.createRigidArea(new Dimension(0, 8)));
		cards.add(packOptions);
		cards.add(Box.createRigidArea(new Dimension(0, 8)));

		JPanel backups = new JPanel(new GridLayout(1, 2, 4, 0));
		JButton export = new JButton("Export");
		export.addActionListener(event -> plugin.exportSave());
		JButton importButton = new JButton("Import");
		importButton.addActionListener(event -> plugin.importSave());
		backups.add(export);
		backups.add(importButton);
		cards.add(compact(backups));
		return cards;
	}

	private JPanel buildSlayerTab()
	{
		JPanel slayer = verticalPanel();
		slayer.setBorder(BorderFactory.createEmptyBorder(8, 4, 8, 4));
		slayer.add(new JLabel("Master for the current task:"));
		slayer.add(Box.createRigidArea(new Dimension(0, 4)));
		slayer.add(compact(masterSelector));
		slayer.add(Box.createRigidArea(new Dimension(0, 8)));
		slayer.add(masterProgress);
		slayer.add(Box.createRigidArea(new Dimension(0, 8)));
		JButton taskDone = new JButton("Task Done (manual)");
		taskDone.addActionListener(event -> plugin.recordManualSlayerTask());
		slayer.add(compact(taskDone));
		slayer.add(Box.createRigidArea(new Dimension(0, 6)));
		JLabel note = new JLabel(htmlBlock("Automatic detection uses the game's completed-task counter. Select the master when accepting a task."));
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		slayer.add(note);
		return slayer;
	}

	private JPanel buildFooter()
	{
		JPanel footer = new JPanel(new BorderLayout(4, 0));
		footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		footer.add(status, BorderLayout.CENTER);
		return compact(footer);
	}

	private void selectMaster(String id)
	{
		for (int index = 0; index < masterSelector.getItemCount(); index++)
		{
			if (masterSelector.getItemAt(index).getId().equals(id))
			{
				masterSelector.setSelectedIndex(index);
				return;
			}
		}
	}

	private static JPanel stat(String label, JLabel value)
	{
		JPanel panel = verticalPanel();
		JLabel heading = new JLabel(label, SwingConstants.CENTER);
		heading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		heading.setAlignmentX(CENTER_ALIGNMENT);
		value.setAlignmentX(CENTER_ALIGNMENT);
		panel.add(heading);
		panel.add(value);
		return panel;
	}

	private static JLabel valueLabel()
	{
		JLabel label = new JLabel("0", SwingConstants.CENTER);
		label.setForeground(Color.WHITE);
		return label;
	}

	private static JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(new Color(255, 152, 31));
		label.setFont(label.getFont().deriveFont(20f));
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static JPanel verticalPanel()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(LEFT_ALIGNMENT);
		return panel;
	}

	private static <T extends JComponent> T compact(T component)
	{
		Dimension preferred = component.getPreferredSize();
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferred.height));
		component.setAlignmentX(LEFT_ALIGNMENT);
		return component;
	}

	private static String htmlBlock(String content)
	{
		return "<html><div style='width: 170px'>" + content + "</div></html>";
	}

	private static String shorten(String value, int maxLength)
	{
		return value.length() <= maxLength ? value : value.substring(0, maxLength - 1) + "…";
	}

	private static String html(String value)
	{
		if (value == null) return "";
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static final class ViewportWidthPanel extends JPanel implements Scrollable
	{
		private ViewportWidthPanel()
		{
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
			setBackground(ColorScheme.DARK_GRAY_COLOR);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.galesong.runecards;

import com.galesong.runecards.model.CardDefinition;
import com.galesong.runecards.model.RuneCardsState;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.swing.JFileChooser;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "RuneCards",
	description = "Card-based Ironman progression powered by Slayer tasks",
	tags = {"ironman", "slayer", "progression", "cards", "challenge"}
)
public class RuneCardsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Notifier notifier;

	@Inject
	private RuneCardsConfig config;

	@Inject
	private RuneCardsDataService dataService;

	@Inject
	private RuneCardsStore store;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PackEarnedOverlay packEarnedOverlay;

	private final SlayerCompletionTracker completionTracker = new SlayerCompletionTracker();
	private RuneCardsEngine engine;
	private RuneCardsPanel panel;
	private NavigationButton navigationButton;
	private boolean profileLoaded;

	@Override
	protected void startUp() throws Exception
	{
		dataService.load();
		engine = new RuneCardsEngine(dataService.getConfig(), dataService.getCards(), new Random());
		engine.loadState(store.load());
		panel = new RuneCardsPanel(this, engine);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/runecards/icon.png");
		navigationButton = NavigationButton.builder()
			.tooltip("RuneCards")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		overlayManager.add(packEarnedOverlay);
		log.debug("RuneCards started with {} cards", dataService.getCards().size());

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loadProfileAndCounters();
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(packEarnedOverlay);
		packEarnedOverlay.hide();
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		panel = null;
		navigationButton = null;
		engine = null;
		profileLoaded = false;
		log.debug("RuneCards stopped");
	}

	@Provides
	RuneCardsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneCardsConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProfileAndCounters();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			packEarnedOverlay.hide();
			profileLoaded = false;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!config.automaticSlayerTasks() || !profileLoaded || engine == null)
		{
			return;
		}

		if (event.getVarbitId() == VarbitID.SLAYER_TASKS_COMPLETED)
		{
			if (completionTracker.observeNormal(event.getValue()))
			{
				recordSlayerTask(engine.getSelectedMasterId(), true);
			}
		}
		else if (event.getVarbitId() == VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED)
		{
			if (completionTracker.observeWilderness(event.getValue()))
			{
				recordSlayerTask("krystilia", true);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RuneCardsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("packEarnedPopup".equals(event.getKey()) && !config.packEarnedPopup())
		{
			packEarnedOverlay.hide();
		}
	}

	void selectMaster(String masterId)
	{
		engine.setSelectedMaster(masterId);
		persistAndRefresh("Current Slayer Master updated.");
	}

	void recordManualSlayerTask()
	{
		recordSlayerTask(engine.getSelectedMasterId(), false);
	}

	void openPack()
	{
		try
		{
			packEarnedOverlay.hide();
			boolean pendingPack;
			synchronized (engine)
			{
				pendingPack = !engine.getState().getPendingPackOptionIds().isEmpty();
				if (!pendingPack)
				{
					engine.openPack();
				}
			}
			if (pendingPack)
			{
				showStatus("Choose one of the cards listed below.");
				return;
			}
			persistAndRefresh("Pack opened. Pick one of the four cards below.");
		}
		catch (IllegalStateException exception)
		{
			showStatus(exception.getMessage());
		}
	}

	void chooseCard(String cardId)
	{
		try
		{
			CardDefinition card = engine.getCard(cardId);
			engine.chooseCard(cardId);
			persistAndRefresh("Unlocked " + (card == null ? cardId : card.getTitle()) + ".");
		}
		catch (IllegalArgumentException exception)
		{
			showStatus(exception.getMessage());
		}
	}

	void completeActiveCard()
	{
		try
		{
			engine.completeActiveCard(readActualLevels());
			persistAndRefresh("Card completed.");
		}
		catch (IllegalStateException exception)
		{
			showStatus(exception.getMessage());
		}
	}

	void exportSave()
	{
		JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Export RuneCards save");
		chooser.setSelectedFile(new File("runecards-save-" + LocalDate.now() + ".json"));
		if (chooser.showSaveDialog(panel) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}
		try
		{
			String json;
			synchronized (engine)
			{
				json = store.serialize(engine.getState());
			}
			Files.writeString(chooser.getSelectedFile().toPath(), json, StandardCharsets.UTF_8);
			showStatus("Save exported.");
		}
		catch (IOException exception)
		{
			log.warn("Unable to export RuneCards save", exception);
			showStatus("The save could not be exported.");
		}
	}

	void importSave()
	{
		JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Import RuneCards save");
		if (chooser.showOpenDialog(panel) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}
		int answer = JOptionPane.showConfirmDialog(panel,
			"Replace this character's RuneCards progress with the selected save?",
			"Import RuneCards save", JOptionPane.YES_NO_OPTION);
		if (answer != JOptionPane.YES_OPTION)
		{
			return;
		}
		try
		{
			String json = Files.readString(chooser.getSelectedFile().toPath(), StandardCharsets.UTF_8);
			RuneCardsState imported = store.deserialize(json);
			if (imported == null)
			{
				throw new IOException("The selected file contained no save data");
			}
			engine.loadState(imported);
			persistAndRefresh("Save imported.");
		}
		catch (Exception exception)
		{
			log.warn("Unable to import RuneCards save", exception);
			showStatus("The selected file is not a valid RuneCards save.");
		}
	}

	private void loadProfileAndCounters()
	{
		clientThread.invokeLater(() ->
		{
			packEarnedOverlay.hide();
			RuneCardsState saved = store.load();
			engine.loadState(saved);
			completionTracker.reset(
				client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED),
				client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED));
			profileLoaded = true;
			refreshPanel();
		});
	}

	private void recordSlayerTask(String masterId, boolean automatic)
	{
		try
		{
			RuneCardsEngine.TaskResult result = engine.completeSlayerTask(masterId);
			String message;
			if (result.isMasterComplete())
			{
				message = "Task recorded. No packs remain for this master.";
			}
			else if (result.isPackFound())
			{
				message = "Task complete — card pack found!";
				if (config.packEarnedPopup())
				{
					packEarnedOverlay.showPackEarned();
				}
				if (automatic && config.notifyPackFound())
				{
					notifier.notify("RuneCards: card pack found!");
				}
			}
			else
			{
				message = "Task complete — no pack this time.";
			}
			persistAndRefresh(message);
		}
		catch (IllegalArgumentException exception)
		{
			showStatus(exception.getMessage());
		}
	}

	private Map<String, Integer> readActualLevels()
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			levels.put(skill.getName(), client.getRealSkillLevel(skill));
		}
		return levels;
	}

	private void persistAndRefresh(String message)
	{
		// Take snapshots and write them on the EDT so concurrent callers cannot
		// overwrite a newer save with an older snapshot.
		RuneCardsEngine currentEngine = engine;
		Runnable save = () ->
		{
			if (engine != currentEngine || currentEngine == null)
			{
				return;
			}
			String json;
			synchronized (currentEngine)
			{
				json = store.serialize(currentEngine.getState());
			}
			store.save(json);
			refreshPanel();
			showStatus(message);
		};
		if (SwingUtilities.isEventDispatchThread())
		{
			save.run();
		}
		else
		{
			SwingUtilities.invokeLater(save);
		}
	}

	private void refreshPanel()
	{
		RuneCardsPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(currentPanel::refresh);
		}
	}

	private void showStatus(String message)
	{
		RuneCardsPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(() -> currentPanel.showStatus(message));
		}
	}
}

package com.galesong.runecards;

import com.galesong.runecards.model.RuneCardsState;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class RuneCardsStore
{
	private static final String STATE_KEY = "state";
	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public RuneCardsStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public RuneCardsState load()
	{
		String json = configManager.getRSProfileConfiguration(RuneCardsConfig.GROUP, STATE_KEY);
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, RuneCardsState.class);
		}
		catch (JsonParseException exception)
		{
			log.warn("Unable to read the saved RuneCards state", exception);
			return null;
		}
	}

	public void save(String json)
	{
		configManager.setRSProfileConfiguration(RuneCardsConfig.GROUP, STATE_KEY, json);
	}

	public String serialize(RuneCardsState state)
	{
		return gson.toJson(state);
	}

	public RuneCardsState deserialize(String json)
	{
		return gson.fromJson(json, RuneCardsState.class);
	}
}

package com.galesong.runecards;

final class SlayerCompletionTracker
{
	private int normalTasks = -1;
	private int wildernessTasks = -1;

	void reset(int normalTasks, int wildernessTasks)
	{
		this.normalTasks = normalTasks;
		this.wildernessTasks = wildernessTasks;
	}

	boolean observeNormal(int current)
	{
		boolean completed = normalTasks >= 0 && current == normalTasks + 1;
		normalTasks = current;
		return completed;
	}

	boolean observeWilderness(int current)
	{
		boolean completed = wildernessTasks >= 0 && current == wildernessTasks + 1;
		wildernessTasks = current;
		return completed;
	}
}

package com.galesong.runecards.model;

import java.util.Collections;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Getter
@NoArgsConstructor
@AllArgsConstructor
public class CardDefinition
{
	public static final String QUEST = "QUEST";

	private String id;
	private String type;
