package com.galesong.runecards;

import com.galesong.runecards.model.CardDefinition;
import com.galesong.runecards.model.Effect;
import com.galesong.runecards.model.Gate;
import com.galesong.runecards.model.MasterProgress;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.HashSet;
import com.galesong.runecards.model.RuneCardsData;
import com.galesong.runecards.model.SlayerMasterDefinition;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class RuneCardsEngineTest
{
	private RuneCardsEngine engine;

	@Before
	public void setUp()
	{
		Map<String, Integer> startingCaps = new HashMap<>();
		startingCaps.put("Mining", 1);
		RuneCardsData config = new RuneCardsData(
			1.0, 4, 1.0, 1.0, 1.0, 0.08, 0.3, 1.0,
			startingCaps,
			Collections.singletonList(new SlayerMasterDefinition("turael", "Turael", 2, "turael.png")));
		CardDefinition miningCard = new CardDefinition(
			"skill_mining_10", "SKILL", "Mining 1 → 10", "Reach Mining level 10.",
			1, false, Collections.emptyList(),
			Collections.singletonList(new Effect(Effect.SET_SKILL_CAP, "Mining", 10)),
			new Gate(Gate.REACH_LEVEL, "Mining", 10));
		engine = new RuneCardsEngine(config, Collections.singletonList(miningCard), new Random(1));
	}

	@Test
	public void opensChoosesAndCompletesCardUsingActualLevel()
	{
		engine.getState().setUnopenedPacks(1);
		List<CardDefinition> options = engine.openPack();
		assertEquals(1, options.size());
		engine.chooseCard("skill_mining_10");
		assertEquals(Integer.valueOf(10), engine.getState().getSkillCaps().get("Mining"));

		assertThrows(IllegalStateException.class,
			() -> engine.completeActiveCard(Collections.singletonMap("Mining", 9)));
		engine.completeActiveCard(Collections.singletonMap("Mining", 10));

		assertNull(engine.getState().getActiveCardId());
		assertEquals(Collections.singletonList("skill_mining_10"), engine.getState().getCompletedCardIds());
	}

	@Test
	public void completedSlayerTaskAwardsPackAtCertainChance()
	{
		RuneCardsEngine.TaskResult result = engine.completeSlayerTask("turael");

		assertEquals(1, engine.getState().getUnopenedPacks());
		assertEquals(1, engine.getState().getSlayerMasters().get("turael").getTasks());
		assertEquals(1, engine.getState().getSlayerMasters().get("turael").getPacksFound());
		assertTrue(result.isPackFound());
	}

	@Test
	public void cannotConsumeAnotherPackWhileChoicesArePending()
	{
		engine.getState().setUnopenedPacks(2);
		engine.openPack();

		assertThrows(IllegalStateException.class, engine::openPack);
		assertEquals(1, engine.getState().getUnopenedPacks());
	}

	@Test
	public void completedNonRepeatableCardCannotBeDrawnAgain()
	{
		engine.getState().setUnopenedPacks(2);
		engine.openPack();
		engine.chooseCard("skill_mining_10");
		assertThrows(IllegalStateException.class, engine::openPack);
		engine.completeActiveCard(Collections.singletonMap("Mining", 10));
		assertThrows(IllegalStateException.class, engine::openPack);
		assertEquals(1, engine.getState().getUnopenedPacks());
	}

	@Test
	public void cannotOpenWithoutPacksOrChooseOutsidePendingOptions()
	{
		assertThrows(IllegalStateException.class, engine::openPack);
		assertThrows(IllegalArgumentException.class, () -> engine.chooseCard("skill_mining_10"));
		assertThrows(IllegalStateException.class, () -> engine.completeActiveCard(Collections.emptyMap()));
		assertNull(engine.getState().getActiveCardId());
	}

	@Test
	public void repeatableCardRemainsEligibleAndDoesNotLowerCaps()
	{
		CardDefinition repeatable = new CardDefinition("repeat", "UNLOCK", "Repeat", "Repeat",
			1, true, Collections.emptyList(),
			Collections.singletonList(new Effect(Effect.SET_SKILL_CAP, "Mining", 10)), null);
		engine = new RuneCardsEngine(engine.getConfig(), Collections.singletonList(repeatable), new Random(1));
		engine.getState().getSkillCaps().put("Mining", 20);
		engine.getState().setUnopenedPacks(2);
		engine.openPack();
		engine.chooseCard("repeat");
		engine.completeActiveCard(Collections.emptyMap());
		assertEquals(Integer.valueOf(20), engine.getState().getSkillCaps().get("Mining"));
		assertTrue(engine.getState().getCompletedCardIds().isEmpty());
		assertEquals(repeatable, engine.openPack().get(0));
	}

	@Test
	public void requirementsNeedBothCapAndCompletedCard()
	{
		CardDefinition locked = new Gson().fromJson("{\"id\":\"locked\",\"requires\":["
			+ "{\"kind\":\"SKILL_CAP_AT_LEAST\",\"skill\":\"Mining\",\"cap\":10},"
			+ "{\"kind\":\"CARD_COMPLETED\",\"cardId\":\"prerequisite\"}]}", CardDefinition.class);
		engine = new RuneCardsEngine(engine.getConfig(), Collections.singletonList(locked), new Random(1));
		engine.getState().setUnopenedPacks(1);
		assertThrows(IllegalStateException.class, engine::openPack);
		engine.getState().getSkillCaps().put("Mining", 10);
		assertThrows(IllegalStateException.class, engine::openPack);
		engine.getState().getCompletedCardIds().add("prerequisite");
		engine.getState().getSkillCaps().put("Mining", 1);
		assertThrows(IllegalStateException.class, engine::openPack);
		engine.getState().getSkillCaps().put("Mining", 10);
		assertEquals(locked, engine.openPack().get(0));
	}

	@Test
	public void unknownRequirementDoesNotMakeCardEligible()
	{
		CardDefinition locked = new Gson().fromJson(
			"{\"id\":\"locked\",\"requires\":[{\"kind\":\"UNKNOWN\"}]}", CardDefinition.class);
		engine = new RuneCardsEngine(engine.getConfig(), Collections.singletonList(locked), new Random(1));
		engine.getState().setUnopenedPacks(1);
		assertThrows(IllegalStateException.class, engine::openPack);
	}

	@Test
	public void packHasDistinctOptionsAndIncludesNonQuest()
	{
		CardDefinition nonQuest = card("skill", "UNLOCK", 1);
		engine = new RuneCardsEngine(engine.getConfig(), Arrays.asList(
			card("q1", CardDefinition.QUEST, 100), card("q2", CardDefinition.QUEST, 100),
			card("q3", CardDefinition.QUEST, 100), card("q4", CardDefinition.QUEST, 100), nonQuest), new Random(1));
		engine.getState().setUnopenedPacks(1);
		List<CardDefinition> options = engine.openPack();
		assertEquals(4, options.size());
		assertEquals(4, new HashSet<>(options).size());
		assertTrue(options.contains(nonQuest));
		assertEquals(1, engine.getState().getPacksOpened());
		assertEquals(engine.getState().getPendingPackOptionIds(), engine.getState().getLastPackOptionIds());
	}

	@Test
	public void weightedSelectionSkipsZeroWeightAtZeroRoll()
	{
		assertEquals("positive", firstWeightedChoice(0, 0, 2).getId());
	}

	@Test
	public void weightedSelectionUsesRelativeWeights()
	{
		assertEquals("first", firstWeightedChoice(0.24, 1, 3).getId());
		assertEquals("positive", firstWeightedChoice(0.25, 1, 3).getId());
		assertEquals("positive", firstWeightedChoice(0.99, 1, 3).getId());
	}

	@Test
	public void allNonPositiveWeightsUseUniformFallback()
	{
		Random random = new Random(1)
		{
			@Override
			public int nextInt(int bound)
			{
				return bound - 1;
			}
		};
		engine = new RuneCardsEngine(engine.getConfig(), Arrays.asList(
			card("negative", CardDefinition.QUEST, -1), card("zero", CardDefinition.QUEST, 0)), random);
		engine.getState().setUnopenedPacks(1);
		assertEquals("zero", engine.openPack().get(0).getId());
	}

	@Test
	public void masterLimitStillRecordsTasksWithoutAwardingPacks()
	{
		engine.completeSlayerTask("turael");
		engine.completeSlayerTask("turael");
		RuneCardsEngine.TaskResult result = engine.completeSlayerTask("turael");
		assertTrue(result.isMasterComplete());
		assertFalse(result.isPackFound());
		assertEquals(2, engine.getState().getUnopenedPacks());
		assertEquals(3, engine.getTotalSlayerTasks());
		assertEquals(0, engine.slayerChance(engine.getState().getSlayerMasters().get("turael")), 0);
	}

	@Test
	public void slayerChanceFallsWithPacksAndPityIsCapped() throws Exception
	{
		RuneCardsDataService data = new RuneCardsDataService(new Gson());
		data.load();
		engine = new RuneCardsEngine(data.getConfig(), data.getCards(), new Random(1));
		MasterProgress progress = engine.getState().getSlayerMasters().get("turael");
		assertEquals(0.84, engine.slayerChance(progress), 0.000001);
		progress.setPacksFound(25);
		assertEquals(0.5075, engine.slayerChance(progress), 0.000001);
		progress.setSinceLastPack(1);
		assertEquals(0.5875, engine.slayerChance(progress), 0.000001);
		progress.setSinceLastPack(100);
		assertEquals(0.8075, engine.slayerChance(progress), 0.000001);
		progress.setPacksFound(0);
		assertEquals(0.9, engine.slayerChance(progress), 0.000001);
	}

	@Test
	public void missedSlayerRollIncrementsPityAndAwardResetsIt() throws Exception
	{
		RuneCardsDataService data = new RuneCardsDataService(new Gson());
		data.load();
		Random random = new Random(1)
		{
			private int rolls;

			@Override
			public double nextDouble()
			{
				return rolls++ == 0 ? 0.99 : 0;
			}
		};
		engine = new RuneCardsEngine(data.getConfig(), data.getCards(), random);
		MasterProgress progress = engine.getState().getSlayerMasters().get("turael");
		assertFalse(engine.completeSlayerTask("turael").isPackFound());
		assertEquals(1, progress.getSinceLastPack());
		assertEquals(0, engine.getState().getUnopenedPacks());
		assertTrue(engine.completeSlayerTask("turael").isPackFound());
		assertEquals(0, progress.getSinceLastPack());
		assertEquals(2, progress.getTasks());
		assertEquals(1, progress.getPacksFound());
	}

	private CardDefinition firstWeightedChoice(double roll, double firstWeight, double secondWeight)
	{
		Random random = new Random(1)
		{
			@Override
			public double nextDouble()
			{
				return roll;
			}
		};
		RuneCardsEngine drawing = new RuneCardsEngine(engine.getConfig(), Arrays.asList(
			card("first", CardDefinition.QUEST, firstWeight),
			card("positive", CardDefinition.QUEST, secondWeight)), random);
		drawing.getState().setUnopenedPacks(1);
		return drawing.openPack().get(0);
	}

	private static CardDefinition card(String id, String type, double weight)
	{
		return new CardDefinition(id, type, id, id, weight, false,
			Collections.emptyList(), Collections.emptyList(), null);
	}
}

package com.galesong.runecards;

import com.galesong.runecards.model.MasterProgress;
import com.galesong.runecards.model.RuneCardsState;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.Random;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class RuneCardsMigrationTest
{
	private final Gson gson = new Gson();
	private final RuneCardsStore store = new RuneCardsStore(null, gson);
	private RuneCardsEngine engine;

	@Before
	public void setUp() throws Exception
	{
		RuneCardsDataService data = new RuneCardsDataService(gson);
		data.load();
		engine = new RuneCardsEngine(data.getConfig(), data.getCards(), new Random(1));
	}

	@Test
	public void repairsNullCollectionsAndMissingDefaults()
	{
		engine.loadState(store.deserialize("{\"taskLog\":null,\"unlockHistory\":null,"
			+ "\"pendingPackOptionIds\":null,\"lastPackOptionIds\":null,\"obtainedCardIds\":null,"
			+ "\"completedCardIds\":null,\"reachedLevels\":null,\"skillCaps\":null,"
			+ "\"slayerMasters\":null,\"selectedMasterId\":\"missing\"}"));
		RuneCardsState state = engine.getState();
		assertNotNull(state.getTaskLog());
		assertNotNull(state.getUnlockHistory());
		assertNotNull(state.getPendingPackOptionIds());
		assertNotNull(state.getLastPackOptionIds());
		assertNotNull(state.getObtainedCardIds());
		assertNotNull(state.getCompletedCardIds());
		assertNotNull(state.getReachedLevels());
		assertEquals(engine.getConfig().getInitialCaps(), state.getSkillCaps());
		assertEquals(engine.getConfig().getMasters().size(), state.getSlayerMasters().size());
		assertEquals("turael", state.getSelectedMasterId());
	}

	@Test
	public void webSaveProgressSurvivesMigrationAndExport()
	{
		String json = "{\"version\":5,\"platform\":\"web-static\",\"unopenedPacks\":3,\"packsOpened\":8,"
			+ "\"skillCaps\":{\"Mining\":40},\"reachedLevels\":{\"Mining\":37},"
			+ "\"activeCardId\":\"unlock-mining-031-040\","
			+ "\"activeGate\":{\"kind\":\"REACH_LEVEL\",\"skill\":\"Mining\",\"level\":40},"
			+ "\"obtainedCardIds\":[\"unlock-mining-031-040\"],\"completedCardIds\":[\"quest_cooks_assistant\"],"
			+ "\"lastPackOptionIds\":[\"unlock-mining-031-040\"],\"lastPackPickedId\":\"unlock-mining-031-040\","
			+ "\"taskLog\":[{\"id\":\"quest_cooks_assistant\",\"title\":\"Cook's Assistant\",\"completedAt\":\"2026-01-01\"}],"
			+ "\"unlockHistory\":[{\"id\":\"unlock-mining-031-040\",\"title\":\"Mining\",\"unlockedAt\":\"2026-01-02\"}],"
			+ "\"slayerMasters\":{\"turael\":{\"tasks\":23,\"packsFound\":8,\"maxPacks\":1,\"sinceLastPack\":4}},"
			+ "\"savedAt\":\"2026-01-03\"}";
		RuneCardsState imported = store.deserialize(json);
		engine.loadState(imported);
		RuneCardsState exported = store.deserialize(store.serialize(engine.getState()));
		assertEquals(5, exported.getVersion());
		assertEquals("runelite", exported.getPlatform());
		assertEquals(3, exported.getUnopenedPacks());
		assertEquals(8, exported.getPacksOpened());
		assertEquals(Integer.valueOf(40), exported.getSkillCaps().get("Mining"));
		assertEquals(Integer.valueOf(1), exported.getSkillCaps().get("Sailing"));
		assertEquals(Integer.valueOf(37), exported.getReachedLevels().get("Mining"));
		assertEquals("unlock-mining-031-040", exported.getActiveCardId());
		assertEquals(40, exported.getActiveGate().getLevel());
		assertEquals(imported.getObtainedCardIds(), exported.getObtainedCardIds());
		assertEquals(imported.getCompletedCardIds(), exported.getCompletedCardIds());
		assertEquals(imported.getLastPackOptionIds(), exported.getLastPackOptionIds());
		assertEquals(imported.getLastPackPickedId(), exported.getLastPackPickedId());
		assertEquals("2026-01-01", exported.getTaskLog().get(0).getCompletedAt());
		assertEquals("2026-01-02", exported.getUnlockHistory().get(0).getUnlockedAt());
		assertEquals("2026-01-03", exported.getSavedAt());
		MasterProgress progress = exported.getSlayerMasters().get("turael");
		assertEquals(23, progress.getTasks());
		assertEquals(8, progress.getPacksFound());
		assertEquals(4, progress.getSinceLastPack());
		assertEquals(50, progress.getMaxPacks());
		assertThrows(IllegalStateException.class,
			() -> engine.completeActiveCard(Collections.singletonMap("Mining", 39)));
		engine.completeActiveCard(Collections.singletonMap("Mining", 40));
		assertTrue(engine.getState().getCompletedCardIds().contains("unlock-mining-031-040"));
		String once = store.serialize(engine.getState());
		engine.loadState(store.deserialize(once));
		assertEquals(once, store.serialize(engine.getState()));
	}

	@Test
	public void importedPendingPackCanStillBeChosen()
	{
		engine.loadState(store.deserialize("{\"pendingPackOptionIds\":[\"unlock-mining-001-010\"],"
			+ "\"selectedMasterId\":\"konar\",\"slayerMasters\":{\"konar\":null}}"));
		assertEquals("konar", engine.getSelectedMasterId());
		assertEquals(70, engine.getState().getSlayerMasters().get("konar").getMaxPacks());
		assertThrows(IllegalStateException.class, engine::openPack);
		engine.chooseCard("unlock-mining-001-010");
		assertEquals(Integer.valueOf(10), engine.getState().getSkillCaps().get("Mining"));
		assertTrue(engine.getState().getPendingPackOptionIds().isEmpty());
	}

	@Test
	public void missingHistoryIsRebuiltFromObtainedIdsInReverseOrder()
	{
		engine.loadState(store.deserialize("{\"obtainedCardIds\":[\"unlock-mining-001-010\",\"unknown-card\"]}"));
		RuneCardsState state = engine.getState();
		assertEquals(2, state.getUnlockHistory().size());
		assertEquals("unknown-card", state.getUnlockHistory().get(0).getTitle());
		assertEquals(engine.getCard("unlock-mining-001-010").getTitle(), state.getUnlockHistory().get(1).getTitle());
		assertNull(state.getUnlockHistory().get(1).getUnlockedAt());
		assertEquals(2, state.getObtainedCardIds().size());
	}

	@Test
	public void explicitlyEmptyHistoryIsPreserved()
	{
		engine.loadState(store.deserialize("{\"obtainedCardIds\":[\"unlock-mining-001-010\"],\"unlockHistory\":[]}"));
		assertTrue(engine.getState().getUnlockHistory().isEmpty());
	}
}

