package com.galesong.runecards;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SlayerCompletionTrackerTest
{
	@Test
	public void onlyAcceptsSingleCounterIncrements()
	{
		SlayerCompletionTracker tracker = new SlayerCompletionTracker();
		tracker.reset(20, 4);

		assertFalse(tracker.observeNormal(20));
		assertTrue(tracker.observeNormal(21));
		assertFalse(tracker.observeNormal(24));
		assertFalse(tracker.observeNormal(2));
		assertTrue(tracker.observeNormal(3));

		assertTrue(tracker.observeWilderness(5));
		assertFalse(tracker.observeWilderness(7));
	}

	@Test
	public void firstObservationAndProfileResetDoNotCountAsTasks()
	{
		SlayerCompletionTracker tracker = new SlayerCompletionTracker();
		assertFalse(tracker.observeNormal(100));
		assertFalse(tracker.observeWilderness(20));
		assertTrue(tracker.observeNormal(101));
		tracker.reset(5, 2);
		assertFalse(tracker.observeNormal(5));
		assertFalse(tracker.observeWilderness(2));
		assertTrue(tracker.observeWilderness(3));
		assertFalse(tracker.observeWilderness(3));
		assertTrue(tracker.observeNormal(6));
	}
}
